-- # Lernfeld 5: Cyberphysische Systeme > ## Testgetriebene Entwicklung > - Grundprinzipien > - Agiles Manifest

INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Steht das Agile Manifest im Widerspruch zu den Prinzipien der testgetriebenen Entwicklung (TDD)?', 2, '[{"text": "Nein", "correct": true, "because": "TDD unterstützt agile Werte wie Flexibilität"}, {"text": "Ja", "correct": false, "because": "TDD passt zum Agilen Manifest"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das Prinzip „Individuen und Interaktionen über Prozesse und Werkzeuge“ im Agilen Manifest für TDD irrelevant?', 2, '[{"text": "Nein", "correct": true, "because": "Teamzusammenarbeit ist in TDD entscheidend"}, {"text": "Ja", "correct": false, "because": "Interaktionen fördern TDD"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann TDD ohne die agile Priorität „Funktionierende Software über umfassende Dokumentation“ effektiv sein?', 2, '[{"text": "Ja", "correct": true, "because": "TDD fokussiert auf funktionierenden Code"}, {"text": "Nein", "correct": false, "because": "Dokumentation sekundär in TDD"}]'),
('00000000-0000-0000-0000-000000000000', 'Erfordert das Agile Manifest, dass TDD zwingend in jedem agilen Projekt angewendet wird?', 2, '[{"text": "Nein", "correct": true, "because": "TDD ist eine Option, kein Muss"}, {"text": "Ja", "correct": false, "because": "Manifest ist flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das Prinzip „Reaktion auf Veränderung über das Befolgen eines Plans“ im Agilen Manifest mit TDD vereinbar?', 2, '[{"text": "Ja", "correct": true, "because": "TDD unterstützt iterative Anpassung"}, {"text": "Nein", "correct": false, "because": "TDD ist anpassungsfähig"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip des Agilen Manifests wird durch TDD am stärksten unterstützt?', 2, '[{"text": "Funktionierende Software über umfassende Dokumentation", "correct": true, "because": "TDD liefert laufend funktionierenden Code"}, {"text": "Individuen und Interaktionen über Prozesse", "correct": false, "because": "Weniger direkt"}, {"text": "Kundenkooperation über Vertragsverhandlungen", "correct": false, "because": "Indirekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Wert des Agilen Manifests spiegelt sich in der iterativen Natur von TDD wider?', 3, '[{"text": "Reaktion auf Veränderung über das Befolgen eines Plans", "correct": true, "because": "TDD passt sich Änderungen an"}, {"text": "Individuen und Interaktionen über Prozesse", "correct": false, "because": "Teamfokus"}, {"text": "Kundenkooperation über Vertragsverhandlungen", "correct": false, "because": "Kundenfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element des Agilen Manifests betont die Bedeutung der Teamzusammenarbeit in TDD?', 2, '[{"text": "Individuen und Interaktionen über Prozesse und Werkzeuge", "correct": true, "because": "Teamarbeit in TDD zentral"}, {"text": "Funktionierende Software über Dokumentation", "correct": false, "because": "Fokus auf Ergebnis"}, {"text": "Reaktion auf Veränderung", "correct": false, "because": "Fokus auf Flexibilität"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt des Agilen Manifests fördert die enge Zusammenarbeit mit dem Kunden in TDD?', 2, '[{"text": "Kundenkooperation über Vertragsverhandlungen", "correct": true, "because": "Kundenfeedback in TDD wichtig"}, {"text": "Individuen und Interaktionen", "correct": false, "because": "Team-intern"}, {"text": "Funktionierende Software", "correct": false, "because": "Ergebnisorientiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip des Agilen Manifests wird durch die ständige Lieferung kleiner TDD-Inkremente unterstützt?', 2, '[{"text": "Funktionierende Software über umfassende Dokumentation", "correct": true, "because": "TDD liefert laufend Ergebnisse"}, {"text": "Reaktion auf Veränderung", "correct": false, "because": "Flexibilität betont"}, {"text": "Kundenkooperation", "correct": false, "because": "Kundenfokus"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Prinzipien des Agilen Manifests werden durch TDD direkt unterstützt?', 4, '[{"text": "Individuen und Interaktionen über Prozesse", "correct": true, "because": "Teamarbeit in TDD"}, {"text": "Funktionierende Software über Dokumentation", "correct": true, "because": "Fokus auf laufenden Code"}, {"text": "Kostenreduktion über Qualität", "correct": false, "because": "Nicht im Manifest"}, {"text": "Reaktion auf Veränderung über Plan", "correct": true, "because": "Iterative Anpassung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Werte des Agilen Manifests fördern die Anwendung von TDD?', 3, '[{"text": "Kundenkooperation", "correct": true, "because": "Feedback in TDD wichtig"}, {"text": "Funktionierende Software", "correct": true, "because": "TDD liefert Ergebnisse"}, {"text": "Langfristige Planung", "correct": false, "because": "Gegen agiles Prinzip"}, {"text": "Reaktion auf Veränderung", "correct": true, "because": "TDD flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte des Agilen Manifests harmonieren mit TDD?', 3, '[{"text": "Iterative Entwicklung", "correct": true, "because": "TDD ist iterativ"}, {"text": "Fokus auf Teamarbeit", "correct": true, "because": "Interaktionen in TDD"}, {"text": "Umfassende Dokumentation", "correct": false, "because": "Gegen TDD-Fokus"}, {"text": "Kundenorientierung", "correct": true, "because": "Tests spiegeln Anforderungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Ausrichtung von TDD am Agilen Manifest?', 4, '[{"text": "Schnelle Anpassungsfähigkeit", "correct": true, "because": "Flexibilität bei Änderungen"}, {"text": "Verbesserte Zusammenarbeit", "correct": true, "because": "Team- und Kundenfokus"}, {"text": "Langfristige Planungssicherheit", "correct": false, "because": "Weniger agil"}, {"text": "Höhere Produktqualität", "correct": true, "because": "Tests sichern Qualität"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen können bei der Verbindung von TDD mit dem Agilen Manifest auftreten?', 3, '[{"text": "Hoher Anfangsinvest in Tests", "correct": true, "because": "TDD erfordert Vorarbeit"}, {"text": "Konflikt mit Kundenkooperation", "correct": false, "because": "Fördert Kooperation"}, {"text": "Unklare Anforderungen", "correct": true, "because": "Tests schwer definierbar"}, {"text": "Teamabhängigkeit", "correct": true, "because": "Interaktionen entscheidend"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) TDD widerspricht dem Agilen Manifest durch starre Prozesse. b) „Funktionierende Software“ wird durch TDD unterstützt.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "TDD flexibel, unterstützt Funktion"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das Agile Manifest fordert TDD als Pflichtmethode. b) TDD fördert die Reaktion auf Veränderungen.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "TDD optional, unterstützt Flexibilität"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) „Kundenkooperation“ im Agilen Manifest harmoniert mit TDD. b) TDD ignoriert „Individuen und Interaktionen“.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kundenfokus passt, Teamarbeit wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) TDD unterstützt „Funktionierende Software“ im Agilen Manifest. b) Das Agile Manifest lehnt TDD wegen Tests ab.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "TDD fördert Funktion, kein Widerspruch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) TDD und das Agile Manifest betonen Teamzusammenarbeit. b) TDD widerspricht der agilen Flexibilität.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Teamarbeit zentral, TDD flexibel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

